const filters = msg.req.query;

let baseQuery = `SELECT a.id, a.data_hora, a.tipo, p.nome AS pessoa_nome, d.tipo AS dispositivo_tipo, e.nome_edificio, pa.nome_perfil
FROM acessos a
JOIN pessoa p ON a.codigo = p.codigo
JOIN dispositivo d ON a.id_dispositivo = d.id_dispositivo
JOIN edificio e ON d.id_edificio = e.id_edificio
LEFT JOIN perfis_acesso pa ON p.id_perfil = pa.id_perfil
WHERE 1=1`;

const params = [];

if (filters.data_inicio) {
  baseQuery += ' AND a.data_hora >= ?';
  params.push(filters.data_inicio);
}
if (filters.data_fim) {
  baseQuery += ' AND a.data_hora <= ?';
  params.push(filters.data_fim);
}
if (filters.nome) {
  baseQuery += ' AND p.nome LIKE ?';
  params.push(`%${filters.nome}%`);
}
if (filters.residencia) {
  baseQuery += ' AND e.nome_edificio LIKE ?';
  params.push(`%${filters.residencia}%`);
}
if (filters.tipo_utilizador) {
  baseQuery += ' AND pa.nome_perfil = ?';
  params.push(filters.tipo_utilizador);
}

baseQuery += ' ORDER BY a.data_hora DESC LIMIT 100';

msg.topic = baseQuery;
msg.params = params;
return msg;
